svg.script:
(function(){
	try{
		const svg = document.currentScript.ownerDocument.documentElement;
		const def = svg.getAttribute('data-default') || '#7d7d7d';
		const hover = svg.getAttribute('data-hover') || '#1e88e5';
		const active = svg.getAttribute('data-active') || '#0b66b2';
		svg.style.setProperty('--icon-color', def);
		svg.addEventListener('mouseenter', ()=> svg.style.setProperty('--icon-color', hover));
		svg.addEventListener('mouseleave', ()=> svg.style.setProperty('--icon-color', def));
		let el = svg.parentNode;
		while(el && el.nodeName && el.nodeName.toLowerCase() !== 'button') el = el.parentNode;
		if(el){
			const btn = el;
			const mo = new MutationObserver(()=>{
				if(btn.classList && btn.classList.contains('is-active')) svg.style.setProperty('--icon-color', active);
				else svg.style.setProperty('--icon-color', def);
			});
			mo.observe(btn, { attributes: true, attributeFilter: ['class'] });
		}
	}catch(e){/* ignore */}
})();
